import {searchMatches,compactStat} from './tatari-model.mjs';
import {resolveBuild,advantage,dojoBadgeIds} from './tatari-stats-model.mjs';
const $=id=>document.getElementById(id),root=new URL('./tatari-data/',import.meta.url),name=x=>typeof x==='string'?x:x?.en||x?.zh||'';
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
const img=(src,alt,cls)=>{const n=el('img',undefined,cls);n.src=new URL(src,root);n.alt=alt;return n;};
let data,mode='calculator';const builds=[{pet:11,tier:1,stars:1,food:1,badgeMode:'none',badges:[]},{pet:22,tier:1,stars:1,food:1,badgeMode:'none',badges:[]}];
function field(title,node){const label=el('div',undefined,'build-field');label.append(el('span',title),node);return label;}
function select(options,value,label){const n=el('select');n.setAttribute('aria-label',label);for(const [v,t,disabled] of options){const o=new Option(t,v);o.disabled=!!disabled;n.append(o);}n.value=value;return n;}
function starPicker(build,index){const wrap=el('div',undefined,'star-control'),button=el('button',undefined,'star-choice');button.type='button';button.setAttribute('aria-label','Choose stars for Tatari '+(index+1));button.append(img('stars/'+String(build.stars).padStart(2,'0')+'.png',build.stars+' stars'));
 const dialog=el('dialog',undefined,'star-dialog');dialog.setAttribute('aria-label','Choose star level');const title=el('h2','Choose star level'),close=el('button','Close','dialog-close');close.type='button';close.onclick=()=>dialog.close();const top=el('div',undefined,'dialog-heading');top.append(title,close);dialog.append(top,el('p','Choose the star image that matches your Tatari.'));
 const grid=el('div',undefined,'star-picker-grid');for(let n=1;n<=84;n++){const option=el('button');option.type='button';option.setAttribute('aria-label',n+' stars');option.setAttribute('aria-pressed',String(n===build.stars));const picture=img('stars/'+String(n).padStart(2,'0')+'.png',n+' stars');picture.loading='lazy';option.append(picture);option.onclick=()=>{build.stars=n;dialog.close();render();};grid.append(option);}dialog.append(grid);button.onclick=()=>dialog.showModal();wrap.append(button,dialog);return wrap;}
function pickerDialog(title,cls=''){const dialog=el('dialog',undefined,'star-dialog '+cls);dialog.setAttribute('aria-label',title);const top=el('div',undefined,'dialog-heading'),close=el('button','Close','dialog-close');close.type='button';close.onclick=()=>dialog.close();top.append(el('h2',title),close);dialog.append(top);return dialog;}
function tatariPicker(build,index){const wrap=el('div',undefined,'tatari-choice-wrap'),unit=data.units.find(u=>u.id===build.pet),button=el('button',undefined,'tatari-choice');button.type='button';button.setAttribute('aria-label','Choose Tatari '+(index+1));button.append(img(unit.forms[0].portrait,name(unit.forms[0].name)),el('span',name(unit.forms[0].name)),el('span','▾','choice-arrow'));
 const dialog=pickerDialog('Choose Tatari '+(index+1),'tatari-picker-dialog'),search=el('input');search.type='search';search.placeholder='🔍 Search Tatari…';search.setAttribute('aria-label','Search Tatari '+(index+1));const grid=el('div',undefined,'tatari-picker-grid');
 const filter=()=>{const matches=data.units.filter(u=>searchMatches(u,search.value));grid.replaceChildren(...matches.map(u=>{const base=u.forms.find(f=>f.evolution===1),option=el('button',undefined,'tatari-picker-option');option.type='button';option.setAttribute('aria-label','Select '+name(base.name));option.setAttribute('aria-pressed',String(u.id===build.pet));option.append(img(u.elementImage,'Element','picker-element'),img(u.roleImage,name(u.role),'picker-role'),img(base.portrait,name(base.name),'picker-portrait'),el('span',name(base.name)));option.onclick=()=>{build.pet=u.id;build.tier=1;dialog.close();render();};return option;}));if(!matches.length)grid.append(el('p','No Tatari matches.'));};search.oninput=filter;filter();dialog.append(search,grid);button.onclick=()=>{dialog.showModal();search.focus();};wrap.append(button,dialog);return wrap;}
const dojoElements=[[2,'Water'],[3,'Fire'],[4,'Grass'],[6,'Rock'],[5,'Lightning']];
function dojoPicker(build,index){const box=el('div',undefined,'dojo-element-picker'),top=el('div',undefined,'badge-heading');top.append(el('span','Dojo Badges'));const account=el('button','Use account settings');account.type='button';account.disabled=true;account.title='Available after login is added';top.append(account);box.append(top);const row=el('div',undefined,'dojo-element-row');
 for(const [element,label] of dojoElements){const matching=data.badges.filter(b=>b.element===element).sort((a,b)=>a.id-b.id),owned=build.badgeMode==='pick'?matching.filter(b=>build.badges.includes(b.id)).length:0,wrap=el('div',undefined,'dojo-element-wrap'),button=el('button',undefined,'dojo-element-button');button.type='button';button.setAttribute('aria-label',label+' dojo for Tatari '+(index+1));button.setAttribute('aria-pressed',String(owned>0));button.append(img(data.units.find(u=>u.element===element).elementImage,label),el('span','Level '+owned));
 const dialog=pickerDialog(label+' Dojo Badges','dojo-dialog'),badges=el('div',undefined,'dojo-badge-row');for(const [i,badge] of matching.entries()){const option=el('button');option.type='button';option.setAttribute('aria-label',label+' badge '+(i+1)+' for Tatari '+(index+1));option.setAttribute('aria-pressed',String(i<owned));option.append(img(badge.image,badge.name),el('span',String.fromCharCode(65+i)));option.onclick=()=>{const keep=build.badges.filter(id=>!matching.some(b=>b.id===id));build.badges=owned===i+1?keep:[...keep,...dojoBadgeIds(data,element,i)];build.badgeMode=build.badges.length?'pick':'none';dialog.close();render();};badges.append(option);}dialog.append(badges);button.onclick=()=>dialog.showModal();wrap.append(button,dialog);row.append(wrap);}
 box.append(row);return box;}
function editor(index){const build=builds[index],unit=data.units.find(u=>u.id===build.pet),panel=el('section',undefined,'build-panel');panel.setAttribute('aria-label','Tatari '+(index+1)+' inputs');panel.append(el('h2',mode==='comparison'?'Tatari Details '+(index+1):'Tatari Details'),tatariPicker(build,index));
 const tiers=el('div',undefined,'build-tiers');tiers.setAttribute('aria-label','Evolution tier for Tatari '+(index+1));for(const f of unit.forms){const b=el('button');b.type='button';b.setAttribute('aria-label',name(f.name)+' tier '+f.evolution);b.setAttribute('aria-pressed',String(f.evolution===build.tier));b.append(img(f.playerhead,name(f.name)));b.onclick=()=>{build.tier=f.evolution;render();};tiers.append(b);}panel.append(tiers);
 const fields=el('div',undefined,'build-field-grid'),level=el('input');level.value=500;level.readOnly=true;level.setAttribute('aria-label','Tatari Level 500 fixed');fields.append(field('Tatari Level',level),field('Stars',starPicker(build,index)));
 const stages=unit.feedingStages.filter(r=>r.stage>=1&&r.stage<=11).sort((a,b)=>a.stage-b.stage),food=select(stages.map(r=>[r.stage,'Food Stage '+r.stage]),build.food,'Food Level for Tatari '+(index+1));food.onchange=()=>{build.food=Number(food.value);render();};fields.append(field('Food Level',food));panel.append(fields,dojoPicker(build,index));return panel;}
function statArtwork(result,stat){const art=el('div',undefined,'result-art');art.append(img('food-stats/'+result.grades[stat]+stat.toLowerCase()+'.png',result.grades[stat]+' '+stat+' food grade'),el('strong',compactStat(result.values[stat])));art.title=stat+' '+Math.floor(result.values[stat]).toLocaleString('en');return art;}
function heading(result,build){const box=el('div',undefined,'result-pet'),card=el('div',undefined,'result-portrait-card');card.append(img('images/tier-'+result.form.evolution+'.png','','result-portrait-background'),img(result.form.portrait,name(result.form.name),'result-portrait'),img('stars/'+String(build.stars).padStart(2,'0')+'.png',build.stars+' stars','result-stars'));box.append(card,el('h2',name(result.form.name)));return box;}
function output(){try{const left=resolveBuild(data,builds[0]),right=mode==='comparison'?resolveBuild(data,builds[1]):null,body=el('section',undefined,'result-panel');body.append(el('h2',mode==='comparison'?'Head-to-head stats':'Estimated stats','result-title'));
 if(!right){body.append(heading(left,builds[0]));const stats=el('div',undefined,'single-stats');for(const a of ['ATK','HP','DEF']){const item=el('div');item.append(statArtwork(left,a));stats.append(item);}body.append(stats);}else{const grid=el('div',undefined,'comparison-grid');grid.append(el('span'),heading(left,builds[0]),heading(right,builds[1]));for(const a of ['ATK','HP','DEF']){grid.append(el('strong',a,'compare-stat-label'));const higher=advantage(left.values[a],right.values[a]);for(const [side,r] of [['left',left],['right',right]]){const item=el('div',undefined,'compare-value'+(side===higher?' stat-higher':''));item.append(statArtwork(r,a));if(side===higher)item.append(el('span','Higher','higher-label'));grid.append(item);}}body.append(grid);}
 $('stats-output').replaceChildren(body);$('tool-status').textContent='';}catch(error){$('tool-status').textContent=error.message;}}
function render(){$('stats-workspace').classList.toggle('comparison-mode',mode==='comparison');$('build-editors').replaceChildren(...(mode==='comparison'?[editor(0),editor(1)]:[editor(0)]));output();}
function changeMode(next){mode=next;for(const m of ['calculator','comparison']){$(m+'-mode').setAttribute('aria-selected',String(m===mode));$(m+'-mode').tabIndex=m===mode?0:-1;}$('stats-workspace').setAttribute('aria-labelledby',mode+'-mode');render();}
for(const m of ['calculator','comparison'])$(m+'-mode').onclick=()=>changeMode(m);document.querySelector('.stats-mode-tabs').onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();changeMode(e.key==='Home'?'calculator':e.key==='End'?'comparison':mode==='calculator'?'comparison':'calculator');$(mode+'-mode').focus();}};
try{const response=await fetch(new URL('roster.json?v=stats-tool',root));if(!response.ok)throw Error('Could not load Tatari data.');data=await response.json();render();}catch(error){$('tool-status').textContent=error.message;$('tool-status').setAttribute('role','alert');}
